      "code": "\n(function () {\n  /* Booking form: send demo requests to the Next contact API */\n  var bookForm = document.getElementById('book-form');\n  var bookStatus = document.getElementById('book-status');\n  if (bookForm && bookStatus && window.fetch) {\n    if (bookForm.dataset.contactHandlerBound === 'true') { return; }\n    bookForm.dataset.contactHandlerBound = 'true';\n    bookForm.addEventListener('submit', function (e) {\n      e.preventDefault();\n      if (e.stopImmediatePropagation) { e.stopImmediatePropagation(); }\n      if (bookForm.dataset.contactSubmitting === 'true') { return; }\n      bookForm.dataset.contactSubmitting = 'true';\n      var button = bookForm.querySelector('button[type=\"submit\"]');\n      if (button) {\n        button.disabled = true;\n        button.dataset.originalText = button.textContent;\n        button.textContent = 'Sending...';\n      }\n      fetch(bookForm.action, { method: 'POST', body: new FormData(bookForm) })\n        .then(function (res) {\n          if (!res.ok) { throw new Error(res.status); }\n          bookForm.hidden = true;\n          bookStatus.textContent = 'Request received — slot options land in your inbox within one business day.';\n        })\n        .catch(function () {\n          bookStatus.textContent = 'Something went wrong — email info@holorai.com and we will sort it by hand.';\n          bookForm.dataset.contactSubmitting = 'false';\n          if (button) {\n            button.disabled = false;\n            button.textContent = button.dataset.originalText || 'Book my demo';\n          }\n        });\n    }, true);\n  }\n})();\n"
